mapper.select:
select

from sh_order
order by id desc limit #{begin}, #{nums}

mapper.update:
update sh_order
set order_status = #{toStatus,jdbcType=TINYINT}
where id = #{id,jdbcType=INTEGER} and order_status = #{fromStatus,jdbcType=TINYINT}

mapper.select:
select

from sh_order
where order_status = 0 and payment_status = 0 and create_time < #{deadline,jdbcType=TIMESTAMP}
order by id asc
limit #{limit}
